const card=(t,d,tg,g)=>{const e=g?`a href="#${g}"`:"div";return `<${e} class="card"><b>${t}</b><small>${d}</small>${tg?"<br>"+tg.map(x=>`<i>${x}</i>`).join(""):""}${g?"<br><i>Read the full explanation</i>":""}</${g?"a":"div"}>`};
