 if(g$("eo")){const P=+g$("e1").value,r=+g$("e2").value/1200,n=+g$("e3").value*12,m=r?P*r*(1+r)**n/((1+r)**n-1):P/n,f=x=>Math.round(x).toLocaleString("en-IN");g$("eo").textContent=`EMI ₹${f(m)}/month · total interest ₹${f(m*n-P)}`;const q=+g$("e4").value;g$("e5").textContent=q>0?`Money doubles in about ${(72/q).toFixed(1)} years`:"Enter a rate above 0"}
