 if(g$("sw")){const r=+g$("cr").value,g=+g$("cg").value,b=+g$("cb").value,hx=[r,g,b].map(v=>v.toString(16).padStart(2,"0")).join("");g$("sw").style.background=`rgb(${r},${g},${b})`;g$("co").textContent=`#${hx.toUpperCase()} · binary ${[r,g,b].map(v=>v.toString(2).padStart(8,"0")).join(" ")}`}
 if(g$("gt")){const b=document.querySelectorAll("[data-g]");b[0].textContent="A = "+GA;b[1].textContent="B = "+GB;g$("gt").textContent=`AND ${GA&GB} · OR ${GA|GB} · XOR ${GA^GB} · NAND ${1-(GA&GB)} · NOT A ${1-GA}`}
